import { Component, memo, useCallback, useMemo, useState } from "react";
import "./ProofOfWork.css";
/* ==========================================================================
   ProofOfWorkImages.jsx
   The six project photos, embedded in the code (base64 JPEG), so the UI shows
   them without any image files to host, copy or link.
   Order = order of the cards in ProofOfWork.jsx. Do not edit by hand.
   To change a photo: replace its string with another "data:image/jpeg;base64,..." value.
   ========================================================================== */
const PROOF_IMAGES = Object.freeze([
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,"
]);


/* ==========================================================================
   ProofOfWork.jsx
   RULES FOLLOWED : no inline style | no <style> tag | no CSS import | no CSS module
                    only .jsx and .css files (no .js) | unique "pow-" class names
                    no repeated markup (data + map) | no function created per item
   NOTE           : load ProofOfWork.css ONCE outside this file
                    (e.g. <link rel="stylesheet" href="/ProofOfWork.css"> in index.html)
   FILES          : ProofOfWork.jsx + ProofOfWork.css + ProofOfWorkImages.jsx (keep together)
   HOW TO USE     : replace the placeholder items in PROJECTS with verified projects and set
                    placeholder: false  to hide the "Image placeholder" badge.
                    "image" accepts an embedded image, a local path or an https link.
                    Without an "image" a coloured placeholder is shown.
   ========================================================================== */

/* ==========================================================================
   SESSION 1 : STATIC DATA
   Frozen so it cannot change at runtime. Filters, cards and fields are all
   rendered from these arrays, so nothing is repeated in the markup.
   ========================================================================== */
const FILTERS = Object.freeze([
  "All", "AI / ML", "IoT", "Robotics", "Hardware", "SaaS", "Automation", "Prototype", "Academic innovation",
]);

// [key in PROJECTS, label shown on the card]
const FIELDS = Object.freeze([
  ["problem", "Problem / Objective"],
  ["tech", "Technology involved"],
  ["work", "What ProJenius worked on"],
  ["outcome", "Current outcome"],
]);

const EMPTY_TEXT = "To be added";

// "tone" picks one of the six placeholder colours defined in the CSS
const PROJECTS = Object.freeze([
  { id: "p1", tone: "a", placeholder: true, tags: ["AI / ML", "Prototype"], title: "Project name to be added", image: PROOF_IMAGES[0] },
  { id: "p2", tone: "b", placeholder: true, tags: ["IoT", "Automation"], title: "Project name to be added", image: PROOF_IMAGES[1] },
  { id: "p3", tone: "c", placeholder: true, tags: ["Robotics", "Hardware"], title: "Project name to be added", image: PROOF_IMAGES[2] },
  { id: "p4", tone: "d", placeholder: true, tags: ["Hardware", "Prototype"], title: "Project name to be added", image: PROOF_IMAGES[3] },
  { id: "p5", tone: "e", placeholder: true, tags: ["SaaS", "Automation"], title: "Project name to be added", image: PROOF_IMAGES[4] },
  { id: "p6", tone: "f", placeholder: true, tags: ["Academic innovation", "IoT"], title: "Project name to be added", image: PROOF_IMAGES[5] },
]);

/* ==========================================================================
   SESSION 2 : HELPERS (pure functions)
   ========================================================================== */
// Safety: only allow local paths, https links or embedded png/jpg/webp images
const safeSrc = (src) =>
  typeof src === "string" && /^(\/(?!\/)|https:\/\/|data:image\/(png|jpe?g|webp);base64,)/.test(src) ? src : "";

/* ==========================================================================
   SESSION 3 : ERROR BOUNDARY (one failing part cannot blank the page)
   Classes : pow-fallback
   ========================================================================== */
class SafeBoundary extends Component {
  state = { failed: false };
  static getDerivedStateFromError() { return { failed: true }; }
  render() {
    return this.state.failed
      ? <p className="pow-fallback" role="alert">This section could not be loaded.</p>
      : this.props.children;
  }
}

/* ==========================================================================
   SESSION 4 : FILTER TAB (one button in the filter bar)
   Classes : pow-filter-item, pow-filter, pow-filter--active
   The click is handled once by the list (SESSION 6) using data-filter,
   so no function is created per tab.
   ========================================================================== */
const FilterTab = memo(function FilterTab({ label, isActive }) {
  return (
    <li className="pow-filter-item">
      <button
        type="button"
        className={`pow-filter${isActive ? " pow-filter--active" : ""}`}
        aria-pressed={isActive}
        data-filter={label}
      >
        {label}
      </button>
    </li>
  );
});

/* ==========================================================================
   SESSION 5 : PROJECT CARD (image, tags, title, detail fields)
   Classes : pow-mono, pow-card, pow-media, pow-media--a..f, pow-media-img, pow-media-badge,
             pow-card-body, pow-tags, pow-tag, pow-card-title, pow-fields,
             pow-field-label, pow-field-value
   ========================================================================== */
const ProjectCard = memo(function ProjectCard({ project }) {
  const image = safeSrc(project.image);
  return (
    <li className="pow-card">
      <div className={`pow-media pow-media--${project.tone}`}>
        {image && <img className="pow-media-img" src={image} alt="" loading="lazy" decoding="async" referrerPolicy="no-referrer" />}
        {project.placeholder && <span className="pow-mono pow-media-badge">Image placeholder</span>}
      </div>
      <div className="pow-card-body">
        <ul className="pow-tags">
          {project.tags.map((tag) => <li key={tag} className="pow-mono pow-tag">{tag}</li>)}
        </ul>
        <h3 className="pow-card-title">{project.title}</h3>
        <dl className="pow-fields">
          {FIELDS.map(([key, label]) => (
            <div key={key}>
              <dt className="pow-mono pow-field-label">{label}</dt>
              <dd className="pow-field-value">{project[key] || EMPTY_TEXT}</dd>
            </div>
          ))}
        </dl>
      </div>
    </li>
  );
});

/* ==========================================================================
   SESSION 6 : MAIN SECTION (header + filters + card grid)
   Classes : pow-section, pow-mono, pow-eyebrow, pow-heading, pow-lead,
             pow-filter-list, pow-grid, pow-empty
   ========================================================================== */
export default function ProofOfWork() {
  const [filter, setFilter] = useState("All");

  // One stable handler for the whole filter list (event delegation)
  const handleSelect = useCallback((event) => {
    const tab = event.target.closest("button[data-filter]");
    if (tab) setFilter(tab.dataset.filter);
  }, []);

  // Recomputed only when the filter changes
  const visible = useMemo(
    () => (filter === "All" ? PROJECTS : PROJECTS.filter((p) => p.tags.includes(filter))),
    [filter]
  );

  return (
    <section className="pow-section" aria-labelledby="pow-heading">
      <header>
        <p className="pow-mono pow-eyebrow">Proof of Work</p>
        <h2 id="pow-heading" className="pow-heading">From Ideas to Working Solutions.</h2>
        <p className="pow-lead">
          Prototypes, products and experiments built with ProJenius, shown with the problem,
          the technology and what came out of it.
        </p>
      </header>

      <ul className="pow-filter-list" aria-label="Filter projects" onClick={handleSelect}>
        {FILTERS.map((label) => (
          <FilterTab key={label} label={label} isActive={label === filter} />
        ))}
      </ul>

      <SafeBoundary>
        {visible.length > 0 ? (
          <ul className="pow-grid" aria-live="polite">
            {visible.map((project) => <ProjectCard key={project.id} project={project} />)}
          </ul>
        ) : (
          <p className="pow-empty" role="status">No projects in this category yet.</p>
        )}
      </SafeBoundary>
    </section>
  );
}
